create table public.businesses (id uuid primary key default gen_random_uuid(), owner_id uuid references public.profiles(id) on delete set null, name text not null, slug text not null unique, description text, website text, phone text, email text, logo_url text, address text, city text, state text, zip text, latitude numeric(9,6), longitude numeric(9,6), google_place_id text, verification_status public.verification_status not null default 'unverified', status public.business_status not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create trigger set_businesses_updated_at before update on public.businesses for each row execute function public.set_updated_at(); create unique index businesses_google_place_id_key on public.businesses(google_place_id) where google_place_id is not null; create index businesses_owner_id_idx on public.businesses(owner_id); create index businesses_status_idx on public.businesses(status); create index businesses_state_city_idx on public.businesses(state,city);
create table public.business_profiles (id uuid primary key default gen_random_uuid(), business_id uuid not null unique references public.businesses(id) on delete cascade, tagline text, about text, cover_image_url text, year_established integer, license_number text, social_links jsonb not null default '{}'::jsonb, highlights text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create trigger set_business_profiles_updated_at before update on public.business_profiles for each row execute function public.set_updated_at();
create table public.professionals (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, title text, bio text, photo_url text, email text, phone text, is_public boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create trigger set_professionals_updated_at before update on public.professionals for each row execute function public.set_updated_at(); create index professionals_business_id_idx on public.professionals(business_id);
create table public.business_services (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, service_id uuid not null references public.services(id) on delete cascade, created_at timestamptz not null default now(), unique(business_id,service_id)); create index business_services_business_id_idx on public.business_services(business_id); create index business_services_service_id_idx on public.business_services(service_id);
create table public.business_service_areas (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, city_id uuid not null references public.cities(id) on delete cascade, created_at timestamptz not null default now(), unique(business_id,city_id)); create index business_service_areas_business_id_idx on public.business_service_areas(business_id); create index business_service_areas_city_id_idx on public.business_service_areas(city_id);
alter table public.businesses enable row level security; alter table public.business_profiles enable row level security; alter table public.professionals enable row level security; alter table public.business_services enable row level security; alter table public.business_service_areas enable row level security;
create policy "Active businesses are publicly readable" on public.businesses for select to anon,authenticated using(status='active'); create policy "Owners can view their own business" on public.businesses for select to authenticated using(owner_id=(select auth.uid())); create policy "Business users can create a business they own" on public.businesses for insert to authenticated with check(owner_id=(select auth.uid())); create policy "Owners can update their own business" on public.businesses for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid())); create policy "Admins manage businesses" on public.businesses for all to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace function public.owns_business(target_business_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.businesses where id=target_business_id and owner_id=(select auth.uid())); $$; create or replace function public.business_is_public(target_business_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.businesses where id=target_business_id and status='active'); $$;
create policy "Business profiles are publicly readable" on public.business_profiles for select to anon,authenticated using(public.business_is_public(business_id)); create policy "Owners manage their business profile" on public.business_profiles for all to authenticated using(public.owns_business(business_id)) with check(public.owns_business(business_id)); create policy "Admins manage business profiles" on public.business_profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Public professionals are publicly readable" on public.professionals for select to anon,authenticated using(is_public=true and public.business_is_public(business_id)); create policy "Owners manage their professionals" on public.professionals for all to authenticated using(public.owns_business(business_id)) with check(public.owns_business(business_id)); create policy "Admins manage professionals" on public.professionals for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Business services are publicly readable" on public.business_services for select to anon,authenticated using(public.business_is_public(business_id)); create policy "Owners manage their business services" on public.business_services for all to authenticated using(public.owns_business(business_id)) with check(public.owns_business(business_id)); create policy "Admins manage business services" on public.business_services for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Business service areas are publicly readable" on public.business_service_areas for select to anon,authenticated using(public.business_is_public(business_id)); create policy "Owners manage their business service areas" on public.business_service_areas for all to authenticated using(public.owns_business(business_id)) with check(public.owns_business(business_id)); create policy "Admins manage business service areas" on public.business_service_areas for all to authenticated using(public.is_admin()) with check(public.is_admin());